import hashlib
import hmac

def pad_key(key: bytes) -> bytes:
    block_size = hashlib.sha256().block_size  # Block size for SHA-256 in bytes (64)
    if len(key) > block_size:
        key = hashlib.sha256(key).digest()

    return key.ljust(block_size, b'\x00')

def expand_key(key: str, msg: str) -> str:
    raw_key = pad_key(key.encode())
    return hmac.new(raw_key, msg.encode(), hashlib.sha256).hexdigest()

def generate_hmac(key: str, message: str) -> str:
    return expand_key(key, message)

def verify_hmac(provided_key: str, message: str, provided_hmac: str) -> bool:
    calculated_hmac = generate_hmac(provided_key, message)
    return hmac.compare_digest(calculated_hmac, provided_hmac)

# Example Usage
if __name__ == ""__main__"":
    key = ""my_secret_key""
    message = ""This is a secure message.""

    # Generate HMAC
    hmac_result = generate_hmac(key, message)
    print(f""Generated HMAC: {hmac_result}"")

    # Verify HMAC
    verification_result = verify_hmac(key, message, hmac_result)
    print(f""Verification Result: {verification_result}"")

    # Example of failed verification
    fake_message = ""This is a tampered message.""
    failed_verification_result = verify_hmac(key, fake_message, hmac_result)
    print(f""Failed Verification Result: {failed_verification_result}"")
