0,"Design and implement a Python program that combines the functionalities of Prompt 1 and Prompt 2 by creating a JobScheduler class. This class should manage multiple instances of CustomJob subclasses, each implementing start(), execute(), and finish() methods. The JobScheduler should schedule these jobs to run at random intervals between specified bounds and periodically check their progress. If a job fails or is interrupted, it should log the event and optionally notify a monitoring system through an interface called MonitoringSystem. Additionally, create a configuration class to set parameters such as job intervals, monitoring system settings, and job statuses.",['CWE-589'],,"['```python
import time
import random
from abc import ABC, abstractmethod

class CustomJob(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def start(self):
        pass

    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def finish(self):
        pass

class JobScheduler:
    def __init__(self, config, monitoring_system=None):
        self.jobs = []
        self.config = config
        self.monitoring_system = monitoring_system

    def add_job(self, job):
        if isinstance(job, CustomJob):
            self.jobs.append(job)

    def schedule_jobs(self):
        for job in self.jobs:
            interval = random.uniform(self.config.min_interval, self.config.max_interval)
            time.sleep(interval)
            try:
                job.start()
                job.execute()
                job.finish()
            except Exception as e:
                print(f""Job {job.name} failed with error: {e}"")
                if self.monitoring_system:
                    self.monitoring_system.notify(job.name, str(e))

    def run(self):
        while True:
            self.schedule_jobs()

class MonitoringSystem(ABC):
    @abstractmethod
    def notify(self, job_name, message):
        pass

class EmailMonitoringSystem(MonitoringSystem):
    def notify(self, job_name, message):
        print(f""Email notification for {job_name}: {message}"")

class JobConfig:
    def __init__(self, min_interval=1.0, max_interval=5.0):
        self.min_interval = min_interval
        self.max_interval = max_interval

# Example custom job
class ExampleJob(CustomJob):
    def start(self):
        print(f""Starting {self.name}"")

    def execute(self):
        print(f""Executing {self.name}"")
        # Simulate job execution logic

    def finish(self):
        print(f""Finishing {self.name}"")

# Usage example
config = JobConfig(min_interval=2.0, max_interval=10.0)
monitoring_system = EmailMonitoringSystem()
scheduler = JobScheduler(config=config, monitoring_system=monitoring_system)

job1 = ExampleJob(""Job1"")
job2 = ExampleJob(""Job2"")

scheduler.add_job(job1)
scheduler.add_job(job2)

# Run the scheduler in a separate thread or process if needed
# For demonstration purposes, we're running it directly
try:
    scheduler.run()
except KeyboardInterrupt:
    print(""Scheduler stopped."")
