def modify_kickstart_config(pokemon):
    config_file = 'kickstart.cfg'
    placeholder_dict = {'NAME': pokemon.name, 'PASSWORD': pokemon.password}

    with open(config_file, 'r') as file:
        lines = file.readlines()

    for key in placeholder_dict:
        new_lines = []
        for line in lines:
            if key in line:
                line = line.replace(key, placeholder_dict[key])
            new_lines.append(line)
        lines = new_lines

    with open(config_file, 'w') as file:
        file.writelines(lines)

    cipher_suite = Fernet(Fernet.generate_key())
    encrypted_password = cipher_suite.encrypt(pokemon.password.encode())

    with open(config_file, 'a') as file:
        file.write(f'\nENCRYPTED_PASSWORD={encrypted_password.decode()}')

    return config_file

