import json

class JsonHandler:
    registry = {}

    @classmethod
    def register_factory(cls, id):
        def decorator(func):
            cls.registry[id] = func
            return func

        return decorator

    @classmethod
    def create_instance(cls, id, data):
        if id not in cls.registry:
            raise ValueError(f""Factory function for ID {id} not found"")
        return cls.registry[id](data)

    @classmethod
    def to_json_string(cls, obj):
        return json.dumps(obj)

    @classmethod
    def from_json_string(cls, json_str):
        return json.loads(json_str)

# Registering factory functions for subclasses

@JsonHandler.register_factory('subclass1')
