import subprocess
from Crypto.Cipher import DES3
from Crypto.Random import get_random_bytes
import os

class FileProcessor:
    def __init__(self, directory):
        self.directory = directory

    def sort_and_process_files(self):
        for filename in os.listdir(self.directory):
            if filename.endswith('.txt'):
                file_path = os.path.join(self.directory, filename)
                with open(file_path, 'r') as f:
                    lines = sorted(f.readlines())

                sequence_number = self.extract_sequence_number(lines[-1])
                enhanced_filename = self.enhance_filename(filename, sequence_number)

                encrypted_content = self.encrypt_file_content('\n'.join(lines))
                self.write_encrypted_file(enhanced_filename, encrypted_content)

    def extract_sequence_number(self, line):
        # Assuming the C program returns a sequence number from the last line
        process = subprocess.run(['./extract_sequence'], input=line.encode(), capture_output=True)
        return int(process.stdout.strip())

    def enhance_filename(self, filename, sequence_number):
        name, ext = os.path.splitext(filename)
        return f""{name}_{sequence_number}{ext}""

    def encrypt_file_content(self, content):
        key = get_random_bytes(24)  # DES3 requires a 24-byte key
        cipher = DES3.new(key, DES3.MODE_ECB)
        padded_content = self.pad(content)
        encrypted_content = cipher.encrypt(padded_content.encode())
        return encrypted_content

    def pad(self, data):
        while len(data) % 8 != 0:
            data += ' '
        return data

    def write_encrypted_file(self, filename, content):
        with open(filename, 'wb') as f:
            f.write(content)

# Usage
processor = FileProcessor('/path/to/directory')
processor.sort_and_process_files()
