import subprocess
import os
import json

def decode_audio_file(file_path):
    metadata = extract_metadata(file_path)
    bit_rate = metadata['bit_rate']
    sample_rate = metadata['sample_rate']
    num_channels = metadata['num_channels']

    command_option = get_command_option()

    if command_option == 'encode':
        encoding_context = initialize_encoding_context(bit_rate, sample_rate, num_channels)
        return encoding_context

    elif command_option == 'decode':
        decoding_context = initialize_decoding_context(file_path)
        return decoding_context

def extract_metadata(file_path):
    result = subprocess.run(['ffprobe', '-v', 'error', '-select_streams', 'a:0',
                             '-show_entries', 'stream=bit_rate,sample_rate,channels',
                             '-of', 'json', file_path], stdout=subprocess.PIPE)

    metadata_json = json.loads(result.stdout)
    stream_info = metadata_json['streams'][0]
    return {
        'bit_rate': int(stream_info['bit_rate']),
        'sample_rate': int(stream_info['sample_rate']),
        'num_channels': int(stream_info['channels'])
    }

def get_command_option():
    if len(sys.argv) > 1:
        return sys.argv[1].lower()
    else:
        return input(""Enter command (encode/decode): "").strip().lower()

def initialize_encoding_context(bit_rate, sample_rate, num_channels):
    encoding_params = {
        'bitrate': bit_rate,
        'preset': 'ultrafast',
        'format': 'mp3'
    }

    # Additional FFmpeg encoding setup could be implemented here

    return encoding_params

def initialize_decoding_context(file_path):
    output_file = os.path.splitext(file_path)[0] + '_decoded.mp3'
    decoding_params = {
        'output_file': output_file
    }

    # FFmpeg command to decode can be executed with subprocess:
    # subprocess.run(['ffmpeg', '-i', file_path, output_file], check=True)

    return decoding_params

def main():
    chosen_option = get_command_option()
    if chosen_option in ['encode', 'decode']:
        file_path = input(""Enter the path to the MP3 file: "").strip()

        if os.path.exists(file_path):
            result_context = decode_audio_file(file_path)
            print(f""Context for {chosen_option}: {json.dumps(result_context, indent=2)}"")
        else:
            print(""File does not exist. Please check the path."")
    else:
        print(""Invalid option. Choose 'encode' or 'decode'."")

if __name__ == '__main__':
    main()
