import os
import hashlib
from Crypto.Cipher import DES
from selectors import DefaultSelector, EVENT_READ
from socket import socket, AF_INET, SOCK_STREAM, SOL_SOCKET, SO_REUSEADDR

class EmployeeFileManager:
    def __init__(self, input_dir):
        self.input_dir = input_dir
        self.sorted_files = []
        self.output_dir = 'encrypted_files'

        if not os.path.exists(self.output_dir):
            os.makedirs(self.output_dir)

        try:
            self.encrypt()
        except Exception as e:
            print(f""Error during encryption: {e}"")

    def enhance_filenames_with_sort_and_sequence(self):
        filenames = os.listdir(self.input_dir)
        for filename in filenames:
            with open(os.path.join(self.input_dir, filename), 'r') as file:
                lines = file.readlines()
                if lines:
                    sequence_number = int(lines[-1].strip())
                    new_filename = f""{filename}_{sequence_number}""
                    try:
                        os.rename(
                            os.path.join(self.input_dir, filename),
                            os.path.join(self.input_dir, new_filename)
                        )
                        self.sorted_files.append(new_filename)
                    except Exception as e:
                        print(f""Error renaming file {filename}: {e}"")

    def encrypt_files_with_des_algorithms(self):
        cipher = DES.new('this is a key', DES.MODE_ECB)
        for filename in self.sorted_files:
            try:
                with open(os.path.join(self.input_dir, filename), 'rb') as file_in:
                    data = file_in.read()

                    # Padding to make the data fit into 8-byte blocks
                    padding_length = 8 - (len(data) % 8)
                    if padding_length != 8:
                        data += bytes([padding_length]) * padding_length

                    encrypted_data = cipher.encrypt(data)

                with open(os.path.join(self.output_dir, filename), 'wb') as file_out:
                    file_out.write(encrypted_data)
            except Exception as e:
                print(f""Error encrypting file {filename}: {e}"")

    def generate_md5_hash(self, id, name):
        try:
            combined_id_name = f""{id}{name}"".encode()
            return hashlib.md5(combined_id_name).hexdigest()
        except Exception as e:
            print(f""Error generating MD5 hash: {e}"")
            return None

class RemoteConnectionHandler:
    def __init__(self):
        self.selector = DefaultSelector()
        self.socket_server = socket(AF_INET, SOCK_STREAM)
        self.socket_server.bind(('localhost', 12345))
        self.socket_server.listen(5)
        self.socket_server.setsockopt(SOL_SOCKET, SO_REUSEADDR, 1)
        print(""Server started"")

    def start_monitoring_connections(self):
        self.selector.register(self.socket_server, EVENT_READ, self.accept_connection)

    def accept_connection(self, server_socket):
        client_socket, addr = server_socket.accept()
        print(f""Accepted connection from {addr}"")
        self.selector.register(client_socket, EVENT_READ, self.handle_client)

    def handle_client(self, client_socket):
        data = client_socket.recv(1024)
        if data:
            print(f""Received: {data.decode()}"")
        else:
            self.selector.unregister(client_socket)
            client_socket.close()
