            self.validate_total_amount(request_data)
            self.calculate_shipping_cost(request_data)
            return ""Order confirmed""
        except ValueError as e:
            return str(e)

    def validate_data_types(self, request_data):
        if not all(isinstance(value, (str, int, float)) for value in request_data.values()):
            raise ValueError(""Invalid data types provided"")

    def validate_total_amount(self, request_data):
        total_amount = float(request_data['totalAmount'])
        if total_amount <= 0:
            raise ValueError(""Total amount must be greater than zero"")

    def calculate_shipping_cost(self, request_data):
        item = request_data['item']
        quantity = int(request_data['quantity'])

        if item not in self.predefined_rates or quantity <= 0:
            raise ValueError(""Invalid item or quantity"")

        shipping_rate_per_unit = self.predefined_rates[item]

        if quantity > 10 and shipping_rate_per_unit == 1.5:
            shipping_rate_per_unit -= 0.25

        shipping_cost = shipping_rate_per_unit * quantity
