import time

def get_count_exceeding_threshold(numbers: list[int], threshold: int) -> int:
    last_called = [0]  # Mutable type to persist across function calls

    def can_invoke():
        current_time = time.time()
        elapsed = current_time - last_called[0]
        if elapsed >= 5:
            last_called[0] = current_time
            return True
        return False

    if not can_invoke():
        raise Exception(""Function is in cooldown. Please wait before calling again."")

    return sum(1 for number in numbers if number > threshold)
