0,"Design and implement a new class in Python named ""WeatherAlertSystem"" that combines functionalities of two provided classes: one for sending SMS alerts based on predefined weather conditions, and another for logging alert messages into a database. The new class should be able to generate SMS alerts when specific weather parameters (such as temperature, humidity, or precipitation levels) exceed predefined thresholds. Additionally, it should log these alert messages along with the timestamp into a database table designated for weather alerts.",['CWE-680'],,"['```python
import datetime
from sms_alert import SMSAlertSender  # Assume this is an existing class
from db_logger import DBLogger         # Assume this is an existing class

class WeatherAlertSystem:
    def __init__(self, db_connection_string):
        self.sms_sender = SMSAlertSender()
        self.db_logger = DBLogger(db_connection_string)

    def check_and_alert(self, temperature, humidity, precipitation, thresholds):
        alerts = []

        if temperature > thresholds['temperature']:
            message = f""High Temperature Alert: {temperature}°C""
            alerts.append(message)

        if humidity > thresholds['humidity']:
            message = f""High Humidity Alert: {humidity}%""
            alerts.append(message)

        if precipitation > thresholds['precipitation']:
            message = f""Heavy Precipitation Alert: {precipitation}mm""
            alerts.append(message)

        for alert in alerts:
            self.send_sms_alert(alert)
            self.log_to_database(alert)

    def send_sms_alert(self, message):
        # Logic to send SMS
        self.sms_sender.send_sms(message)

    def log_to_database(self, message):
        timestamp = datetime.datetime.now()
        data = {
            'message': message,
            'timestamp': timestamp
        }
        # Log to database
        self.db_logger.log(data)

# Example usage:
# thresholds = {'temperature': 35, 'humidity': 80, 'precipitation': 50}
# weather_system = WeatherAlertSystem('your_db_connection_string')
# weather_system.check_and_alert(36, 85, 20, thresholds)
