# Python code for the font caching function

import os
from hashlib import md5

def get_default_font_dir():
    return ""/usr/share/fonts""  # Set default font directory

def manage_font_cache(cache_root):
    if not cache_root:
        cache_root = get_default_font_dir()

    font_cache = {}

    for root, dirs, files in os.walk(cache_root):
        for file in files:
            if file.endswith("".ttf""):
                file_path = os.path.join(root, file)
                with open(file_path, 'rb') as f:
                    content = f.read()

                hash_value = md5(content).hexdigest()

                if file_path not in font_cache:
                    print(f""Caching {file}..."")
                    font_cache[file_path] = {""hash"": hash_value, ""content"": content}
                    # Assign font to a reused state
                else:
                    print(f""Reusing cached font: {file}"")

    return font_cache

# Example usage
font_cache = manage_font_cache(None)
```

