class NFAPI_LTE_CELL_T:
    def __init__(self, rai, tac, state):
        self.RAI = rai
        self.TAC = tac
        self.State = state

def generate_rai():
    # Example algorithm to create a valid RAI value (randomly generated for simulation)
    return f""{random.randint(1000, 9999)}-{random.randint(1, 99):02d}""

def generate_tac():
    # Example algorithm to create a valid TAC value
    return random.randint(10000, 49999)

def initialize_database(size):
    return {}

def populate_database(db, size):
    for i in range(size):
        rai = generate_rai()
        tac = generate_tac()
        state = random.randint(0, 2)
        cell = NFAPI_LTE_CELL_T(rai, tac, state)
        db[i] = cell

def validate_structure(cell):
    if not (1000 <= int(cell.RAI.split('-')[0]) <= 9999):
        return False
    if not (1 <= int(cell.RAI.split('-')[1])) or len(cell.RAI.split('-')[1]) != 2:
        return False
    if not (10000 <= cell.TAC <= 49999):
        return False
    if not (0 <= cell.State <= 2):
        return False
    return True

def simulate_validation(db):
    for key, cell in db.items():
        assert validate_structure(cell), f""Validation failed for cell at index {key}""

# Usage example:
database = initialize_database(10)
populate_database(database, 10)
simulate_validation(database)

# Displaying the database content
for idx, cell in database.items():
    print(f""Index: {idx}, RAI: {cell.RAI}, TAC: {cell.TAC}, State: {cell.State}"")
