import json
import sys

def read_json(file_path):
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        print(f""Error: The file {file_path} was not found."")
        sys.exit(1)
    except json.JSONDecodeError:
        print(""Error: The file contains invalid JSON."")
        sys.exit(1)

def extract_data(data, keys):
    extracted = {}
    for key in keys:
        if isinstance(key, list):  # Handling nested keys
            sub_data = data
            try:
                for k in key:
                    sub_data = sub_data[k]
                extracted['.'.join(map(str, key))] = sub_data
            except KeyError:
                continue
        else:  # Single level key
            if key in data:
                extracted[key] = data[key]
    return extracted

def write_json(data, output_file_path, indent=None):
    with open(output_file_path, 'w') as file:
        json.dump(data, file, indent=indent)

if __name__ == ""__main__"":
    input_file = ""input.json""
    output_file = ""output.json""
    keys_to_extract = [""key1"", [""nested_key1"", ""sub_key2""], ""key3""]

    data = read_json(input_file)
    extracted_data = extract_data(data, keys_to_extract)

    write_json(extracted_data, output_file, indent=4)  # Optional custom formatting with indentation
