        self.temperature = reading['temperature']
        self.humidity = reading['humidity']

class SensorDataManager:
    def __init__(self, data_source):
        self.data_registry = {}
        self.timestamp = time.time()
        self.temperature = random.uniform(20.0, 30.0)
        self.humidity = random.randint(0, 100)
        self.data_source = data_source

    def add_sensor_data(self):
        sensor_data = SensorData(self.data_source.get_next_reading())
        return sensor_data

    def sort_sensor_data(self, sensor_data_list):
        return sorted(sensor_data_list, key=lambda x: x.timestamp)

    def compute_md5(self, file_path):
        with open(file_path, 'rb') as file:
            return md5(file.read()).hexdigest()

    # Extend factory function registry with method to add new functions.
    def add_factory_function(self, id_number: int,
