import json
from abc import ABC, abstractmethod

# Part 1: Enhanced OpenSSL Functionality

class LoggingManager(ABC):
    @abstractmethod
    def log(self, message, level=""INFO""):
        pass

class BasicLogger(LoggingManager):
    def __init__(self):
        self.logs = []

    def log(self, message, level=""INFO""):
        entry = f""[{level}] {message}""
        print(entry)
        self.logs.append(entry)

class AbstractConfigParser(ABC):
    @abstractmethod
    def parse(self, file_path):
        pass

class BasicConfigParser(AbstractConfigParser):
    def __init__(self):
        self.configurations = {}

    def parse(self, file_path):
        try:
            with open(file_path) as config_file:
                self.configurations = json.load(config_file)
        except Exception as e:
            logger.log(f""Failed to load configuration: {e}"", ""ERROR"")

class OpenSSLOptionsParser(BasicConfigParser, BasicLogger):
    def __init__(self):
        BasicConfigParser.__init__(self)
        BasicLogger.__init__(self)
        self.options = []

    def set_options(self, option_array):
        for option in option_array:
            if not isinstance(option, str):
                self.log(f""Invalid option type: {type(option)}"", ""ERROR"")
                continue
            self.options.append(option)

    def load_libraries(self, library_name):
        try:
            # Simulate dynamic loading of OpenSSL libraries
            self.log(f""Dynamically loading library: {library_name}"")
            # LoadLibrary equivalent for OpenSSL (pseudo-code)
            # lib = ctypes.CDLL(library_name)
        except Exception as e:
            self.log(f""Failed to load library: {e}"", ""ERROR"")

    def configure_cipher(self, cipher_name):
        if cipher_name not in [""AES-256-CBC"", ""DES-EDE3""]:
            self.log(f""Unsupported cipher algorithm: {cipher_name}"", ""WARNING"")
            return
        self.log(f""Configured cipher: {cipher_name}"")

# Part 2: JSON Object Management

class InstanceRegistryManager:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id_, factory_function):
        if id_ in self.registry:
            raise ValueError(""Factory with this ID already exists."")
        self.registry[id_] = factory_function

    def get_factory(self, id_):
        return self.registry.get(id_)

    def create_instance(self, id_, *args, **kwargs):
        factory_function = self.get_factory(id_)
        if not factory_function:
            raise ValueError(f""No factory found for ID: {id_}"")
        return factory_function(*args, **kwargs)

# Example subclass and usage
class BaseClass:
    @classmethod
    def from_json(cls, data_str):
        return cls(**json.loads(data_str))

    def to_json(self):
        return json.dumps(self.__dict__)

class CustomSubclass(BaseClass):
    def __init__(self, name, value):
        self.name = name
        self.value = value

# Adding a factory function
registry_manager = InstanceRegistryManager()
registry_manager.add_factory(""custom"", CustomSubclass)

# Creating an instance using the registry
