# instance_registry_manager.py

import json

class InstanceRegistryManager:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id_, factory_func):
        if not callable(factory_func):
            raise ValueError(""Factory function must be callable"")
        self.registry[id_] = factory_func

    def create_instance(self, id_, *args, **kwargs):
        factory_func = self.get_factory(id_)
        if factory_func:
            return factory_func(*args, **kwargs)
        else:
            raise ValueError(f""No factory registered for ID: {id_}"")

    def get_factory(self, id_):
        return self.registry.get(id_)

# Example subclass and factory function
class CustomObject:
    def __init__(self, data):
        self.data = data

def custom_object_factory(data):
    return CustomObject(json.loads(data))

# Usage example
if __name__ == ""__main__"":
    registry_manager = InstanceRegistryManager()
    registry_manager.add_factory(""custom"", custom_object_factory)

    json_data = '{""key"": ""value""}'
    instance = registry_manager.create_instance(""custom"", json_data)
    print(instance.data)
```

