            current_time = time.time()

            # Clean up old requests
            if user_ip in requests:
                requests[user_ip] = [timestamp for timestamp in requests[user_ip] if current_time - timestamp < 60]

            if len(requests.get(user_ip, [])) >= max_requests_per_minute:
                return jsonify({""error"": ""Rate limit exceeded""}), 429

            requests.setdefault(user_ip, []).append(current_time)
            return f(*args, **kwargs)

        return wrapped
    return decorator

def log_request(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        logging.info(f""Request from {request.remote_addr} at {time.asctime()}"")
        response = f(*args, **kwargs)
        if not isinstance(response, tuple):
            response = jsonify(response), 200
        return response

    return decorated_function

app = Flask(__name__)

@app.route('/product', methods=['GET', 'POST'])
@log_request
@rate_limit(60)  # Limit to 60 requests per minute per user IP
def product_handler():
    try:
        service = ProductService()

        if request.method == 'GET':
            user_id = request.args.get('user_id')
            product_id = request.args.get('product_id')
            quantity = int(request.args.get('quantity', 1))

            if not all([user_id, product_id]):
                return jsonify({""error"": ""Missing parameters""}), 400

        elif request.method == 'POST':
            data = request.json
            user_id = data.get('user_id')
            product_id = data.get('product_id')
            quantity = int(data.get('quantity', 1))

            if not all([user_id, product_id]):
                return jsonify({""error"": ""Missing parameters""}), 400

        # Check cache first
        cached_product = cache.get(product_id)
        if cached_product:
            product_details = cached_product
        else:
            product_details = service.get_product_details(product_id)
            # Cache the result with a simple hash of sensitive data for security
            cache[product_id] = {**product_details, ""price"": hashlib.sha256(str(product_details[""price""]).encode()).hexdigest()}

        total_cost = product_details['price'] * quantity

        response_data = {
            ""user_id"": user_id,
            ""product_details"": product_details,
            ""quantity"": quantity,
            ""total_cost"": total_cost,
            ""shipping_cost"": 10,  # Example static value
            ""tax"": 5               # Example static value
        }

        return jsonify(response_data)

    except Exception as e:
        logging.error(f""Error handling request: {str(e)}"")
        return jsonify({""error"": ""Internal server error""}), 500

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    app.run(ssl_context='adhoc')  # Run with SSL/TLS encryption
