import os
from cryptography.fernet import Fernet
import socket
import threading
import hashlib

class EmployeeFileManager:
    def __init__(self, input_dir, output_dir):
        self.input_dir = input_dir
        self.output_dir = output_dir

    def sort_files_by_last_line(self):
        files = [f for f in os.listdir(self.input_dir) if os.path.isfile(os.path.join(self.input_dir, f))]
        sorted_files = {}

        for file in files:
            with open(os.path.join(self.input_dir, file), 'r') as f:
                lines = f.readlines()
                last_line = lines[-1].strip() if lines else """"
                sequence_number = int(last_line) if last_line.isdigit() else None
                sorted_files[file] = sequence_number

        return dict(sorted(sorted_files.items(), key=lambda item: (item[1], item[0])))

    def generate_key(self):
        return Fernet.generate_key()

    def encrypt_file(self, file_path, key):
        fernet = Fernet(key)

        with open(file_path, 'rb') as file:
            original_data = file.read()

        encrypted_data = fernet.encrypt(original_data)

        with open(os.path.join(self.output_dir, os.path.basename(file_path)), 'wb') as encrypted_file:
            encrypted_file.write(encrypted_data)

    def encrypt_files(self):
        if not os.path.exists(self.output_dir):
            os.makedirs(self.output_dir)

        sorted_files = self.sort_files_by_last_line()
        key = self.generate_key()

        for file, _ in sorted_files.items():
            file_path = os.path.join(self.input_dir, file)
            self.encrypt_file(file_path, key)


class RemoteConnectionHandler:
    def __init__(self, host='localhost', port=8080):
        self.host = host
        self.port = port

    def handle_client(self, client_socket, address):
        try:
            while True:
                request = client_socket.recv(1024)
                if not request:
                    break

                # Process the incoming data (authentication/verification, etc.)
                print(f""Received data from {address}: {request.decode()}"")
                # For demonstration purposes, just echo back
                client_socket.sendall(request)

        finally:
            client_socket.close()

    def start_server(self):
        server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server.bind((self.host, self.port))
        server.listen(5)  # Listen for up to 5 connections

        print(f""Server started on {self.host}:{self.port}"")

        try:
            while True:
                client_socket, address = server.accept()
                print(f""Connection from {address} has been established."")

                client_handler = threading.Thread(
                    target=self.handle_client,
                    args=(client_socket, address)
                )
                client_handler.start()

        finally:
            server.close()


def generate_md5_hash(value):
