import random
import ipaddress
import threading
import logging
from statistics import mean

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define constraints
SUBNET = ""192.168.1.0/24""
PORT_RANGE = (1024, 65535)

class NETWORK_USER_DATA_PDU_T:
    def __init__(self, user_id, ip_address, port_number):
        self.user_id = user_id
        self.ip_address = ip_address
        self.port_number = port_number

def generate_ip_address(subnet):
    network = ipaddress.ip_network(subnet)
    return str(random.choice(list(network.hosts())))

def generate_port_number():
    return random.randint(*PORT_RANGE)

def validate_structure(structure):
    try:
        # Validate IP address within subnet
        if not ipaddress.IPv4Address(structure.ip_address) in ipaddress.ip_network(SUBNET):
            raise ValueError(""Invalid IP Address"")

        # Validate port number range
        if not (PORT_RANGE[0] <= structure.port_number <= PORT_RANGE[1]):
            raise ValueError(""Port number out of valid range"")

    except Exception as e:
        logging.error(f""Validation error: {e}"")
        return False

    return True

def generate_structure(user_id):
    ip_address = generate_ip_address(SUBNET)
    port_number = generate_port_number()
    structure = NETWORK_USER_DATA_PDU_T(user_id, ip_address, port_number)

    if validate_structure(structure):
        return structure
    else:
        return None

def worker(user_ids, results, index_start):
    for i in range(index_start, len(user_ids)):
        result = generate_structure(user_ids[i])
        if result:
            results.append(result)

def generate_structures(n):
    user_ids = [f""user_{i+1}"" for i in range(n)]
    results = []

    num_threads = 4
    threads = []
    chunk_size = len(user_ids) // num_threads

    for i in range(num_threads):
        index_start = i * chunk_size
        if i == num_threads - 1: # Last thread may take the remaining work
            index_end = len(user_ids)
        else:
            index_end = (i + 1) * chunk_size

        t = threading.Thread(target=worker, args=(user_ids[index_start:index_end], results, index_start))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return results

def calculate_average_ip_value(structures):
    total_ip_sum = 0
    for structure in structures:
        ip_parts = list(map(int, structure.ip_address.split('.')))
        ip_int = (ip_parts[0] << 24) + (ip_parts[1] << 16) + (ip_parts[2] << 8) + ip_parts[3]
        total_ip_sum += ip_int
    return mean(total_ip_sum for _ in structures)

def port_distribution(structures):
    distribution = {port: 0 for port in range(PORT_RANGE[0], PORT_RANGE[1]+1)}
    for structure in structures:
        if structure.port_number in distribution:
            distribution[structure.port_number] += 1
    return distribution

if __name__ == ""__main__"":
    n = 100  # Number of structures to generate
    generated_structures = generate_structures(n)

    logging.info(f""Generated {len(generated_structures)} valid structures."")

    avg_ip_value = calculate_average_ip_value(generated_structures)
    port_dist = port_distribution(generated_structures)

    print(""Average IP Address Value:"", avg_ip_value)
    print(""Port Number Distribution:"")
    for port, count in port_dist.items():
        if count > 0:
            print(f""Port {port}: {count}"")
