import psycopg2
from psycopg2 import pool
from urllib.parse import urlparse

def initialize_database_connection(db_url: str, use_pooling: bool = False, connect_timeout: int = None):
    def is_valid_url(url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except ValueError:
            return False

    if not is_valid_url(db_url):
        raise ValueError(""Invalid database URL"")

    conn_params = {
        'dbname': urlparse(db_url).path[1:],  # Extract dbname from path
        'user': urlparse(db_url).username or '',
        'password': urlparse(db_url).password or '',
        'host': urlparse(db_url).hostname,
        'port': urlparse(db_url).port
    }

    try:
        if connect_timeout is not None:
            conn_params['connect_timeout'] = connect_timeout

        if use_pooling:
            # Use connection pooling
            db_pool = pool.SimpleConnectionPool(1, 20, **conn_params)
            return db_pool
        else:
            # Establish a single database connection
            conn = psycopg2.connect(**conn_params)
            return conn

    except Exception as e:
        raise ConnectionError(f""Failed to connect to the database: {e}"")
