import json
from datetime import datetime, timedelta
import jwt

def validate_jwt_token_response(token_response):
    try:
        token_data = json.loads(token_response)
        token_type = token_data.get(""token_type"")
        access_token = token_data.get(""access_token"")
        exp_timestamp = token_data.get(""exp"")

        if (
            token_type == ""JWT""
            and access_token is not None
            and exp_timestamp is not None
        ):
            current_time = datetime.now()
            expiration_time = datetime.fromtimestamp(exp_timestamp)

            if expiration_time > current_time:
                # Check if the expiration timestamp is within 5 minutes of the current time
                if expiration_time - current_time <= timedelta(minutes=5):
                    try:
                        # Verify the JWT using a dummy secret key for demonstration purposes
                        jwt.decode(access_token, ""dummy-secret-key"", algorithms=[""HS256""])
                        return True
                    except jwt.exceptions.ExpiredSignatureError:
                        return False
                else:
                    return False  # Token expires too far in the future

    except json.JSONDecodeError:
        pass  # Return False in case of invalid JSON format

    return False  # Return False for any other error cases


def test_validate_jwt_token_response():
    test_cases = [
        {
            ""input"": '{""token_type"": ""JWT"", ""access_token"": ""eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c"", ""exp"": 1696502400}',
