# xml_processor.py

import lxml.etree as ET
import json
import csv
import yaml

def validate_xml(xml_string, schema_path):
    try:
        with open(schema_path, 'rb') as schema_file:
            schema_root = ET.XML(schema_file.read())
        schema = ET.XMLSchema(schema_root)
        xml_doc = ET.fromstring(xml_string)
        schema.assertValid(xml_doc)
        return True
    except (ET.DocumentInvalid, ET.XMLSyntaxError) as e:
        print(f""XML validation error: {e}"")
        return False

def parse_xml_to_dict(xml_string):
    root = ET.fromstring(xml_string)
    def recursive_parse(element):
        return {
            element.tag: {
                child.tag: recursive_parse(child)
                for child in list(element)
            } or element.text
        }
    return recursive_parse(root)

def xml_to_json(xml_string, schema_path):
    if validate_xml(xml_string, schema_path):
        data_dict = parse_xml_to_dict(xml_string)
        return json.dumps(data_dict, indent=4)
    else:
        raise ValueError(""Invalid XML structure."")

def xml_to_csv(xml_string, schema_path, output_file):
    if validate_xml(xml_string, schema_path):
        data_dict = parse_xml_to_dict(xml_string)
        with open(output_file, mode='w', newline='') as file:
            writer = csv.writer(file)
            for key, value in data_dict.items():
                if isinstance(value, dict):
                    for sub_key, sub_value in value.items():
                        writer.writerow([key, sub_key, sub_value])
    else:
        raise ValueError(""Invalid XML structure."")

def xml_to_yaml(xml_string, schema_path, output_file):
    if validate_xml(xml_string, schema_path):
        data_dict = parse_xml_to_dict(xml_string)
        with open(output_file, 'w') as file:
            yaml.dump(data_dict, file, default_flow_style=False)
    else:
        raise ValueError(""Invalid XML structure."")
