def filter_even_numbers(input_list):
    try:
        # Check if all elements in the input_list are integers
        if not all(isinstance(x, int) for x in input_list):
            raise ValueError(""All items in the list must be integers."")

        # Filter and return even numbers from the input list
        even_numbers = [num for num in input_list if num % 2 == 0]
        return even_numbers

    except ValueError as e:
