from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

def decrypt_aes(ciphertext, key, mode='ECB', padding_method='PKCS7', iv=None):
    try:
        # Ensure key length is valid
        if len(key) not in [16, 24, 32]:
            raise ValueError(""Invalid key size. Must be 128, 192 or 256 bits."")

        cipher_mode = AES.MODE_ECB if mode.upper() == 'ECB' else AES.MODE_CBC

        # Initialize the cipher
        if mode.upper() == 'CBC':
            if iv is None:
                raise ValueError(""IV must be provided for CBC mode."")
            cipher = AES.new(key, cipher_mode, iv)
        else:
            cipher = AES.new(key, cipher_mode)

        # Decrypt and unpad based on padding method
        plaintext = cipher.decrypt(ciphertext)

        if padding_method.upper() == 'PKCS7':
            plaintext = unpad(plaintext, AES.block_size, style='pkcs7')
        elif padding_method.upper() == 'ISO10126':
            plaintext = unpad(plaintext, AES.block_size, style='iso7816')
        elif padding_method.upper() == 'OPENSSL':
            plaintext = unpad(plaintext, AES.block_size)

        return plaintext
    except Exception as e:
        logging.error(f""Decryption failed: {e}"")
        raise

def read_file(file_path):
    try:
        with open(file_path, 'rb') as file:
            return file.read()
    except IOError as e:
        logging.error(f""Error reading file {file_path}: {e}"")
        raise

def write_file(file_path, data):
    try:
        with open(file_path, 'wb') as file:
            file.write(data)
    except IOError as e:
        logging.error(f""Error writing to file {file_path}: {e}"")
        raise

def main():
    # Example usage
    mode = input(""Enter AES mode (ECB/CBC): "")
    padding_method = input(""Enter padding method (PKCS7/ISO10126/OpenSSL): "")

    key_file = input(""Enter path to key file: "")
    encrypted_file = input(""Enter path to encrypted file: "")
    decrypted_file = input(""Enter output path for decrypted file: "")

    try:
        key = read_file(key_file)
        ciphertext = read_file(encrypted_file)

        iv = None
        if mode.upper() == 'CBC':
            iv_length = AES.block_size  # Typically 16 bytes for AES
            iv = ciphertext[:iv_length]
            ciphertext = ciphertext[iv_length:]

        plaintext = decrypt_aes(ciphertext, key, mode=mode, padding_method=padding_method, iv=iv)
        write_file(decrypted_file, plaintext)

        logging.info(""Decryption completed successfully."")
    except Exception as e:
        logging.error(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()
```

**Note**: This code uses the `pycryptodome` library. You can install it using `pip install pycryptodome`.']",0,[0],[],True,0,0,0,

