import random

class UserLocationInfo:
    def __init__(self):
        self.records = []

    def initialize_array(self, size):
        for _ in range(size):
            record = {
                'UE_ID': None,
                'Serving_Network_ID': None,
                'Location_Area_Code': None
            }
            self.records.append(record)

    def populate_records(self):
        for record in self.records:
            record['UE_ID'] = random.randint(1000, 9999)
            record['Serving_Network_ID'] = random.choice(['NetA', 'NetB', 'NetC'])
            record['Location_Area_Code'] = f""{random.randint(10, 99)}-{random.randint(100, 999)}""

    def validate_records(self):
        for record in self.records:
            if not isinstance(record['UE_ID'], int) or not (1000 <= record['UE_ID'] <= 9999):
                return False
            if record['Serving_Network_ID'] not in ['NetA', 'NetB', 'NetC']:
                return False
            lac_parts = record['Location_Area_Code'].split('-')
            if len(lac_parts) != 2 or not (10 <= int(lac_parts[0]) <= 99) or not (100 <= int(lac_parts[1]) <= 999):
                return False
        return True

# Example usage:
