0,"Design and implement a command-line tool that allows users to manage a library's collection of books. The tool should support adding new books, updating existing book information, removing books, listing all books in the collection, and searching for books by title or author. Users can specify the output format for listing or searching results as either plain text or a CSV file. The application should also include an option to print a manual page with usage instructions.",['CWE-121'],,"['```python
import argparse
import csv
import os

class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author):
        book = {'title': title, 'author': author}
        self.books.append(book)
        print(f""Added: {title} by {author}"")

    def update_book(self, old_title, new_title=None, new_author=None):
        for book in self.books:
            if book['title'] == old_title:
                if new_title:
                    book['title'] = new_title
                if new_author:
                    book['author'] = new_author
                print(f""Updated: {old_title}"")
                return
        print(""Book not found."")

    def remove_book(self, title):
        for i, book in enumerate(self.books):
            if book['title'] == title:
                del self.books[i]
                print(f""Removed: {title}"")
                return
        print(""Book not found."")

    def list_books(self, format_type='text'):
        if format_type == 'csv':
            with open('books.csv', mode='w', newline='') as file:
                writer = csv.DictWriter(file, fieldnames=['title', 'author'])
                writer.writeheader()
                for book in self.books:
                    writer.writerow(book)
            print(""Books list saved to books.csv"")
        else:
            for book in self.books:
                print(f""Title: {book['title']}, Author: {book['author']}"")

    def search_books(self, query, format_type='text'):
        results = [book for book in self.books if query.lower() in book['title'].lower() or query.lower() in book['author'].lower()]
        if not results:
            print(""No books found."")
            return

        if format_type == 'csv':
            with open('search_results.csv', mode='w', newline='') as file:
                writer = csv.DictWriter(file, fieldnames=['title', 'author'])
                writer.writeheader()
                for book in results:
                    writer.writerow(book)
            print(""Search results saved to search_results.csv"")
        else:
            for book in results:
                print(f""Title: {book['title']}, Author: {book['author']}"")

    def display_manual(self):
        manual = """"""
        Usage instructions:

        To add a new book:
          python library_tool.py add --title ""Book Title"" --author ""Author Name""

        To update an existing book:
          python library_tool.py update --old-title ""Old Book Title"" [--new-title ""New Book Title""] [--new-author ""New Author Name""]

        To remove a book:
          python library_tool.py remove --title ""Book Title""

        To list all books (default text, use --format csv for CSV):
          python library_tool.py list [--format text|csv]

        To search for books by title or author (default text, use --format csv for CSV results):
          python library_tool.py search --query ""Search Query"" [--format text|csv]

        To display this manual:
          python library_tool.py help
        """"""
        print(manual)

def main():
    parser = argparse.ArgumentParser(description='Library Management Tool')
    subparsers = parser.add_subparsers(dest='command')

    add_parser = subparsers.add_parser('add', help='Add a new book')
    add_parser.add_argument('--title', required=True, help=""Book title"")
    add_parser.add_argument('--author', required=True, help=""Author name"")

    update_parser = subparsers.add_parser('update', help='Update an existing book')
    update_parser.add_argument('--old-title', required=True, help=""Current book title"")
    update_parser.add_argument('--new-title', help=""New book title"")
    update_parser.add_argument('--new-author', help=""New author name"")

    remove_parser = subparsers.add_parser('remove', help='Remove a book')
    remove_parser.add_argument('--title', required=True, help=""Book title to be removed"")

    list_parser = subparsers.add_parser('list', help='List all books')
    list_parser.add_argument('--format', choices=['text', 'csv'], default='text', help=""Output format (default: text)"")

    search_parser = subparsers.add_parser('search', help='Search for a book by title or author')
    search_parser.add_argument('--query', required=True, help=""Search query"")
    search_parser.add_argument('--format', choices=['text', 'csv'], default='text', help=""Output format (default: text)"")

    args = parser.parse_args()

    library = Library()

    if args.command == 'add':
        library.add_book(args.title, args.author)
    elif args.command == 'update':
        library.update_book(args.old_title, args.new_title, args.new_author)
    elif args.command == 'remove':
        library.remove_book(args.title)
    elif args.command == 'list':
        library.list_books(args.format)
    elif args.command == 'search':
        library.search_books(args.query, args.format)
    else:
        library.display_manual()

if __name__ == ""__main__"":
    main()
