def modify_kickstart(config_path, params, password_line=""new_password_line""):
    try:
        with open(config_path, 'r') as file:
            config_data = file.read()

        for key, value in params.items():
            config_data = re.sub(f""{key}"", value, config_data)

        config_data += f""\n{password_line}""

        with open(config_path, 'w') as file:
            file.write(config_data)

    except Exception as e:
        raise Exception(f""Failed to modify kickstart file: {e}"")

