0,"Design and implement a command-line tool that enables users to manage a personal finance portfolio. The tool should support adding new financial assets, updating existing asset information, removing assets, listing all assets with their current values, and calculating the total portfolio value. Users can specify the output format for listing or calculating results as either plain text or a CSV file. The application should also include an option to print a manual page with usage instructions and provide alerts for significant changes in asset values exceeding predefined thresholds.",['CWE-121'],,"['```python
import argparse
import csv
import sys

class FinancePortfolio:
    def __init__(self):
        self.assets = {}

    def add_asset(self, name, value):
        if name not in self.assets:
            self.assets[name] = value
            print(f""Asset '{name}' added with value: {value}"")
        else:
            print(f""Asset '{name}' already exists."")

    def update_asset(self, name, new_value):
        if name in self.assets:
            old_value = self.assets[name]
            self.assets[name] = new_value
            print(f""Updated asset '{name}' from {old_value} to {new_value}"")
        else:
            print(f""Asset '{name}' not found."")

    def remove_asset(self, name):
        if name in self.assets:
            del self.assets[name]
            print(f""Removed asset '{name}'."")
        else:
            print(f""Asset '{name}' not found."")

    def list_assets(self, output_format='text'):
        if output_format == 'csv':
            writer = csv.writer(sys.stdout)
            writer.writerow([""Name"", ""Value""])
            for name, value in self.assets.items():
                writer.writerow([name, value])
        else:
            for name, value in self.assets.items():
                print(f""{name}: {value}"")

    def total_value(self):
        return sum(self.assets.values())

    def alert_thresholds(self, threshold=10.0):
        alerts = []
        for name, value in self.assets.items():
            if abs(value - self.assets.get(name, 0)) > threshold:
                alerts.append(f""Significant change detected in '{name}'"")
        return alerts

def print_manual():
    print(""""""
Usage: finance_tool.py [options]

Options:
  --add <name> <value>   Add a new asset with the given name and value.
  --update <name> <new_value>
                         Update an existing asset's value.
  --remove <name>        Remove an asset from the portfolio.
  --list <format>        List all assets. Format: text or csv
  --total                Calculate the total portfolio value.
  --alert <threshold>    Print alerts for significant changes over threshold.
  --manual               Display this manual page.
"""""")

def main():
    parser = argparse.ArgumentParser(description=""Manage your personal finance portfolio."")
    parser.add_argument('--add', nargs=2, metavar=('name', 'value'), type=float)
    parser.add_argument('--update', nargs=2, metavar=('name', 'new_value'), type=float)
    parser.add_argument('--remove', metavar='name')
    parser.add_argument('--list', choices=['text', 'csv'], default='text')
    parser.add_argument('--total', action='store_true')
    parser.add_argument('--alert', type=float)
    parser.add_argument('--manual', action='store_true')

    args = parser.parse_args()
    portfolio = FinancePortfolio()

    if args.manual:
        print_manual()
        return

    if args.add:
        portfolio.add_asset(args.add[0], args.add[1])

    if args.update:
        portfolio.update_asset(args.update[0], args.update[1])

    if args.remove:
        portfolio.remove_asset(args.remove)

    if args.list is not None:
        portfolio.list_assets(args.list)

    if args.total:
        print(f""Total Portfolio Value: {portfolio.total_value()}"")

    if args.alert is not None:
        alerts = portfolio.alert_thresholds(args.alert)
        for alert in alerts:
            print(alert)

if __name__ == '__main__':
    main()
