import datetime

# Assuming existing classes for SMS dispatching and database recording
class SMSSender:
    def send_sms(self, message):
        print(f""Sending SMS: {message}"")

class DatabaseRecorder:
    def record_alert(self, alert_data):
        print(f""Recording in database: {alert_data}"")

class WeatherAlertSystem:
    def __init__(self, sms_sender, db_recorder, temp_limit, humidity_limit, rainfall_limit):
        self.sms_sender = sms_sender
        self.db_recorder = db_recorder
        self.temp_limit = temp_limit
        self.humidity_limit = humidity_limit
        self.rainfall_limit = rainfall_limit

    def check_weather_and_alert(self, temperature, humidity, rainfall):
        alerts = []

        if temperature > self.temp_limit:
            alert_msg = f""Temperature alert: {temperature} exceeds limit of {self.temp_limit}""
            alerts.append(alert_msg)

        if humidity > self.humidity_limit:
            alert_msg = f""Humidity alert: {humidity} exceeds limit of {self.humidity_limit}""
            alerts.append(alert_msg)

        if rainfall > self.rainfall_limit:
            alert_msg = f""Rainfall alert: {rainfall} exceeds limit of {self.rainfall_limit}""
            alerts.append(alert_msg)

        if alerts:
            timestamp = datetime.datetime.now().isoformat()
            for alert in alerts:
                self.sms_sender.send_sms(alert)
                self.db_recorder.record_alert({""timestamp"": timestamp, ""alert"": alert})

# Example usage
sms_sender = SMSSender()
db_recorder = DatabaseRecorder()
weather_system = WeatherAlertSystem(sms_sender, db_recorder, temp_limit=30, humidity_limit=70, rainfall_limit=50)

