0,"Create a program that generates and manages a collection of game characters. Each character will have an ID, a randomly generated name, a level, and a randomly assigned weapon. The program should allow the user to add new characters, view existing characters, and delete characters. It should also provide the ability to sort the characters based on their level or weapon type.",['CWE-680'],,"['```python
import random
import string

class Character:
    def __init__(self, character_id):
        self.character_id = character_id
        self.name = self.generate_random_name()
        self.level = random.randint(1, 100)
        self.weapon = random.choice(['Sword', 'Bow', 'Axe', 'Staff'])

    @staticmethod
    def generate_random_name():
        return ''.join(random.choices(string.ascii_uppercase, k=6))

class CharacterManager:
    def __init__(self):
        self.characters = {}
        self.next_id = 1

    def add_character(self):
        char = Character(self.next_id)
        self.characters[self.next_id] = char
        print(f""Added character: {char.name} (ID: {char.character_id}, Level: {char.level}, Weapon: {char.weapon})"")
        self.next_id += 1

    def view_characters(self):
        if not self.characters:
            print(""No characters to display."")
            return
        for char in self.characters.values():
            print(f""ID: {char.character_id}, Name: {char.name}, Level: {char.level}, Weapon: {char.weapon}"")

    def delete_character(self, character_id):
        if character_id in self.characters:
            del self.characters[character_id]
            print(f""Character with ID {character_id} deleted."")
        else:
            print(""Character not found."")

    def sort_characters_by_level(self):
        sorted_chars = sorted(self.characters.values(), key=lambda x: x.level, reverse=True)
        for char in sorted_chars:
            print(f""ID: {char.character_id}, Name: {char.name}, Level: {char.level}, Weapon: {char.weapon}"")

    def sort_characters_by_weapon(self):
        sorted_chars = sorted(self.characters.values(), key=lambda x: x.weapon)
        for char in sorted_chars:
            print(f""ID: {char.character_id}, Name: {char.name}, Level: {char.level}, Weapon: {char.weapon}"")

def main():
    manager = CharacterManager()

    while True:
        choice = input(""Choose an action: [A]dd, [V]iew, [D]elete, Sort by [L]evel, Sort by [W]eapon, [Q]uit: "").upper()

        if choice == 'A':
            manager.add_character()
        elif choice == 'V':
            manager.view_characters()
        elif choice == 'D':
            char_id = int(input(""Enter character ID to delete: ""))
            manager.delete_character(char_id)
        elif choice == 'L':
            manager.sort_characters_by_level()
        elif choice == 'W':
            manager.sort_characters_by_weapon()
        elif choice == 'Q':
            break
        else:
            print(""Invalid option. Please try again."")

if __name__ == ""__main__"":
    main()
