import requests
from datetime import datetime
from collections import defaultdict

class FinanceTool:
    def __init__(self):
        self.users = {}
        self.current_user = None
        self.portfolios = defaultdict(dict)

    def create_user(self, username):
        if username in self.users:
            print(f""User {username} already exists."")
        else:
            self.users[username] = {'portfolios': {}}
            print(f""User {username} created."")

    def switch_user(self, username):
        if username not in self.users:
            print(f""User {username} does not exist. Please create it first."")
        else:
            self.current_user = username
            print(f""Switched to user: {username}"")

    def create_portfolio(self, portfolio_name):
        if portfolio_name in self.users[self.current_user]['portfolios']:
            print(f""Portfolio {portfolio_name} already exists."")
        else:
            self.portfolios[portfolio_name] = {
                'assets': {},
                'budgets': defaultdict(float),
                'transactions': [],
                'categories': {}
            }
            self.users[self.current_user]['portfolios'][portfolio_name] = portfolio_name
            print(f""Portfolio {portfolio_name} created for user: {self.current_user}"")

    def delete_portfolio(self, portfolio_name):
        if portfolio_name in self.portfolios:
            del self.portfolios[portfolio_name]
            del self.users[self.current_user]['portfolios'][portfolio_name]
            print(f""Deleted portfolio: {portfolio_name}"")
        else:
            print(f""Portfolio {portfolio_name} does not exist."")

    def update_asset_value(self, portfolio_name, asset_id):
        # Placeholder for API integration
        response = requests.get(""API_ENDPOINT_FOR_REAL_TIME_DATA"", params={""asset"": asset_id})
        data = response.json()
        if ""price"" in data:
            self.portfolios[portfolio_name]['assets'][asset_id] = data[""price""]
            print(f""Updated value for {asset_id} in portfolio: {portfolio_name}"")

    def set_budget(self, portfolio_name, category, amount):
        self.portfolios[portfolio_name]['budgets'][category] = amount
        print(f""Budget of {amount} set for category '{category}' in portfolio: {portfolio_name}"")

    def log_transaction(self, portfolio_name, asset_id, amount, transaction_type):
        timestamp = datetime.now().isoformat()
        self.portfolios[portfolio_name]['transactions'].append({
            'asset': asset_id,
            'amount': amount,
            'type': transaction_type,
            'timestamp': timestamp
        })
        print(f""Logged {transaction_type} for {amount} of {asset_id} in portfolio: {portfolio_name}"")

    def generate_report(self, portfolio_name):
        # Placeholder for generating and displaying reports
        total_assets = sum(asset['price'] for asset in self.portfolios[portfolio_name]['assets'].values())
        print(f""Total assets value for {portfolio_name}: {total_assets}"")

    def add_asset_category(self, portfolio_name, asset_id, category):
        if 'categories' not in self.portfolios[portfolio_name]:
            self.portfolios[portfolio_name]['categories'] = {}
        self.portfolios[portfolio_name]['categories'][asset_id] = category
        print(f""Asset {asset_id} categorized as '{category}' in portfolio: {portfolio_name}"")

    def suggest_rebalancing(self, portfolio_name):
        # Placeholder for rebalancing algorithm
        print(f""Suggesting rebalancing for portfolio: {portfolio_name}"")

    def handle_multi_currency(self, transaction_amount, currency_code):
        conversion_rate = 1.0  # Placeholder for actual conversion logic
        if currency_code != 'USD':
            converted_amount = transaction_amount * conversion_rate
            return converted_amount
        return transaction_amount

    def integrate_with_banking_api(self, banking_service):
        # Placeholder for OAuth authentication and integration with external services
        print(f""Integrated with banking service: {banking_service}"")

    def set_custom_alerts(self, portfolio_name, threshold, alert_type='email'):
        # Placeholder for setting up alerts
        print(f""Custom alert set for portfolio {portfolio_name} on reaching {threshold} via {alert_type}"")


# Main program execution starts here

