finance_tool.switch_user(""john_doe"")
finance_tool.create_portfolio(""John's Portfolio"")
finance_tool.set_budget(""John's Portfolio"", ""groceries"", 300.0)
finance_tool.log_transaction(""John's Portfolio"", ""AAPL"", 150, ""buy"")
finance_tool.update_asset_value(""John's Portfolio"", ""AAPL"")

# Save user data
with open('finance_data.json', 'w') as file:
    json.dump({""users"": finance_tool.users, ""portfolios"": dict(finance_tool.portfolios)}, file)

# Load user data (for persistence)
if os.path.exists('finance_data.json'):
