import random

class EPSBearerContext:
    def __init__(self, valid=True):
        self.valid = valid

class UE_ID:
    def __init__(self, id_value):
        self.id_value = id_value

class EPS_ATTACH_ACCEPT_CAUSE:
    causes = [""cause_1"", ""cause_2"", ""cause_3"", ""cause_4""]

    @staticmethod
    def random_cause():
        return random.choice(EPS_ATTACH_ACCEPT_CAUSE.causes)

class MME_ATTACH_ACCEPT:
    def __init__(self, bearer_context, ue_id, attach_accept_cause):
        self.bearer_context = bearer_context
        self.ue_id = ue_id
        self.attach_accept_cause = attach_accept_cause

def generate_mme_attach_accept_instances(n):
    instances = []
    for _ in range(n):
