        ue_id = UE_ID(id_value=random.randint(1, 1000))
        attach_accept_cause = EPS_ATTACH_ACCEPT_CAUSE.random_cause()

        instance = MME_ATTACH_ACCEPT(
            bearer_context=eps_bearer_context,
            ue_id=ue_id,
            attach_accept_cause=attach_accept_cause
        )
        instances.append(instance)

    return instances

# Example usage:
