import random

class APDU:
    def __init__(self):
        self.APDU_APDU_DATA = self.generateAPDUData()
        self.Sequence_Number = self.generateSequenceNumber()

    def generateAPDUData(self):
        data_length = random.randint(1, 10)
        return ''.join(random.choice('0123456789abcdef') for _ in range(data_length)).encode()

    def generateSequenceNumber(self):
        LCG_A = 16807
        LCG_C = 0
        LCG_M = 256

        seed = random.randint(1, 255)

        # Linear Congruential Generator (LCG) formula: X(n+1) = (A*Xn + C) % M
        return (LCG_A * seed + LCG_C) % LCG_M


def populateAPDUList(apduList, count):
    if not apduList or count <= 0:
        print(""Invalid input"")
        return

    for i in range(count):
        apdu = APDU()
        pdu = NFAPI_CRC_INDICATION_PDU_T(mac=""MAC_"" + str(i), rnti=i, crcflag=bool(random.getrandbits(1)), crcvalue=random.randint(0, 255))

        # Assign generated data and sequence number
        pdu.apdu = apdu

        apduList.append(pdu)

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, mac, rnti, crcflag=False, crcvalue=0):
        self.mac = mac
        self.rnti = rnti
        self.crcflag = crcflag
        self.crcvalue = crcvalue
        self.apdu = None


def generate_random_pdu(count):
    apdu_list = []
    populateAPDUList(apdu_list, count)
    return apdu_list


def verify_pdu(pdu):
    if not pdu or not pdu.apdu:
        print(""Invalid PDU"")
        return False

    # Simple verification: Check the presence of data
    return bool(pdu.apdu.APDU_APDU_DATA)


def check_cyclic_redundancy_check(mac):
    # Placeholder for CRC check logic specific to a MAC address
    # This function can be enhanced as per actual CRC checking requirements.
    if mac.startswith(""MAC_""):
        return True
    return False

# Example usage:
if __name__ == ""__main__"":
    pdu_list = generate_random_pdu(5)
    for pdu in pdu_list:
        print(f""MAC: {pdu.mac}, RNTI: {pdu.rnti}, CRC Flag: {pdu.crcflag}, CRC Value: {pdu.crcvalue}"")
        if verify_pdu(pdu):
            print(f""Valid APDU Data: {pdu.apdu.APDU_APDU_DATA.decode()}, Sequence Number: {pdu.apdu.Sequence_Number}"")

