class Account:
    def __init__(self, account_number, account_holder_name, initial_balance=0):
        self.account_number = account_number
        self.account_holder_name = account_holder_name
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f""Deposited: {amount}. New Balance: {self.balance}"")
        else:
            print(""Deposit amount must be positive."")

    def withdraw(self, amount):
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
                print(f""Withdrew: {amount}. Remaining Balance: {self.balance}"")
            else:
                print(""Insufficient funds for this withdrawal."")
        else:
            print(""Withdrawal amount must be positive."")

    def display_balance(self):
        print(f""Account Holder: {self.account_holder_name}, Account Number: {self.account_number}, Current Balance: {self.balance}"")

    def calculate_interest(self, interest_rate):
        if interest_rate >= 0:
            interest = self.balance * (interest_rate / 100)
            return interest
        else:
            print(""Interest rate must be non-negative."")
            return 0

# Example usage:
account1 = Account('12345678', 'John Doe', 1000)

account1.display_balance()
account1.deposit(500)
account1.withdraw(200)
interest = account1.calculate_interest(5)
print(f""Calculated Interest: {interest}"")
```

