        ('ip_address', c_char_p),
        ('port_number', c_int)
    ]

def generate_network_user_data_structures(N, subnet=""192.168.0.0/24"", start_port=1024, end_port=65535):
    structures = []
    logging.basicConfig(filename='generation.log', level=logging.INFO, format='%(asctime)s:%(levelname)s:%(message)s')

    counter = 1
    try:
        for _ in range(N):
            ip_address = generate_valid_ip(subnet)
            port_number = generate_valid_port(start_port, end_port)
            structure = NETWORK_USER_DATA_PDU_T(user_id=counter, ip_address=ip_address.encode('utf-8'), port_number=port_number)
            structures.append(structure)
            counter += 1

        return structures

    except Exception as e:
        logging.error(f""Error occurred during generation: {str(e)}"")
        return None

def generate_valid_ip(subnet):
    network_ip = socket.inet_aton(socket.gethostbyname(subnet.split('/')[0]))
    prefix_len = int(subnet.split('/')[1])

    while True:
        ip_bin = bytearray(network_ip)
        for i in range(32 - prefix_len, 32):
            ip_bin[i // 8] |= (1 << (7 - (i % 8)))

        network_ip = bytes(ip_bin)
        ip_str = socket.inet_ntoa(network_ip)
        if validate_ip(ip_str) and validate_subnet(ip_str, prefix_len, subnet.split('/')[0]):
            return ip_str

def validate_subnet(ip_address, prefix_len, base_ip):
    cidr_mask = (b'\xff' * (prefix_len // 8)) + (b'\x00' * (4 - (prefix_len // 8)))
    if prefix_len % 8:
        cidr_mask += bytes([0xFF << (8 - (prefix_len % 8)) & 0xFF])

    base_ip = socket.inet_aton(base_ip)
    ip_bin = socket.inet_aton(ip_address)

    return int.from_bytes(ip_bin[:len(cidr_mask)], 'big') & int.from_bytes(cidr_mask, 'big') == int.from_bytes(base_ip[:len(cidr_mask)], 'big')

def validate_ip(ip_address):
    try:
        socket.inet_aton(ip_address)
        return True
    except socket.error:
        return False

def generate_valid_port(start_port, end_port): 
    return random.randint(start_port, end_port)
