        dest_ip = random_ip()

        # Check if the generated IPs are valid and not localhost
        while (source_ip == ""127.0.0.1"" or socket.inet_aton(source_ip) in [socket.inet_aton('255.255.255.255'), socket.INADDR_ANY]):
            source_ip = random_ip()

        while (dest_ip == ""127.0.0.1"" or socket.inet_aton(dest_ip) in [socket.inet_aton('255.255.255.255'), socket.INADDR_ANY]):
            dest_ip = random_ip()

        source_port = random_port()
        dest_port = random_port()

        entry = {
            'id': entry_id,
            'source_ip': source_ip,
            'dest_ip': dest_ip,
            'source_port': source_port,
            'dest_port': dest_port
