from random import choice, randint, sample
import string

def generate_random_string(length):
    return ''.join(choice(string.ascii_lowercase) for _ in range(length))

def generate_table_name():
    table_prefix = ['users', 'orders', 'products', 'invoices']
    return f""{choice(table_prefix)}_{generate_random_string(5)}""

def generate_query(operation, table_name):
    if operation == ""SELECT"":
        columns = "", "".join(sample([""id"", ""name"", ""email"", ""price""], randint(1, 3)))
        query = f""SELECT {columns} FROM {table_name}""
    elif operation == ""INSERT"":
        values = "", "".join(f""'{generate_random_string(8)}'"" for _ in range(randint(1, 4)))
        columns = "", "".join(sample([""id"", ""name"", ""email"", ""price""], randint(1, 3)))
        query = f""INSERT INTO {table_name} ({columns}) VALUES ({values})""
    elif operation == ""UPDATE"":
        set_clause = "", "".join(f""{col}='{generate_random_string(8)}'"" for col in sample([""id"", ""name"", ""email"", ""price""], randint(1, 3)))
        query = f""UPDATE {table_name} SET {set_clause}""
    elif operation == ""DELETE"":
        condition = f""id={randint(1, 100)}""
        query = f""DELETE FROM {table_name} WHERE {condition}""
    return query

def generate_db_operations(n):
    operations = [""SELECT"", ""INSERT"", ""UPDATE"", ""DELETE""]
    db_operations = []

    for i in range(n):
        table_name = generate_table_name()
        operation_type = choice(operations)
        sql_query = generate_query(operation_type, table_name)
        operation_id = randint(1000, 9999)

        entry = {
            ""operation_id"": operation_id,
            ""table_name"": table_name,
            ""operation_type"": operation_type,
            ""sql_query"": sql_query
        }

        db_operations.append(entry)

    return db_operations

# Example usage:
if __name__ == ""__main__"":
    operations = generate_db_operations(10)
    for op in operations:
        print(op)
