import random
from PIL import Image
import subprocess
import os

class CryptoRandomGenerator:
    def __init__(self, min_val, max_val):
        self.min_val = min_val
        self.max_val = max_val

    def generate_float(self):
        return self.min_val + (self.max_val - self.min_val) * random.random()

    def generate_int(self):
        return int(self.min_val + (self.max_val - self.min_val) * random.random())

    def parse_tiff_image(self, file_path):
        try:
            image = Image.open(file_path)
            image_data = list(image.getdata())
            return image_data
        except IOError as e:
            print(f""Error opening TIFF image: {e}"")
            return None

    def create_cipher_from_option(self, option):
        # Assuming OpenSSL is available and set up in the environment
        try:
            if option == 'encrypt':
                command = ['openssl', 'enc', '-aes-256-cbc']
            elif option == 'decrypt':
                command = ['openssl', 'enc', '-d', '-aes-256-cbc']
            else:
                raise ValueError(""Invalid option, must be 'encrypt' or 'decrypt'"")

            process = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE)
            return process
        except Exception as e:
            print(f""Error creating cipher: {e}"")
            return None

def process_file(filename, sort_criteria, encryption_mode='DES'):
    with open(filename, 'r') as file:
        lines = file.readlines()

    sorted_lines = sorted(lines, key=sort_criteria)

    if encryption_mode == 'DES':
        sequence_numbers = extract_sequence_numbers(sorted_lines)

        for i in range(len(sorted_lines)):
            enhanced_filename = f""{filename[:-4]}_{sequence_numbers[i]}.encrypted""
            with open(enhanced_filename, 'w') as new_file:
                new_file.write(sorted_lines[i])

def extract_sequence_numbers(lines):
    sequence_numbers = []
    try:
        for line in lines:
            # Example command using openssl
            process = subprocess.Popen(['openssl', 'des3', '-d'], stdin=subprocess.PIPE, stdout=subprocess.PIPE)
            output, _ = process.communicate(input=line.encode())
            decrypted_line = output.decode().strip()
            sequence_number = int(decrypted_line.split(',')[0])  # Assuming the sequence number is the first element
            sequence_numbers.append(sequence_number)
    except Exception as e:
        print(f""Error extracting sequence numbers: {e}"")

    return sequence_numbers

